mapper.select:
select m.message_id, m.message_title, m.message_type, cast(m.message_content as char) as message_content, m.message_level, m.biz_source, m.biz_id, m.redirect_url, m.recipient_id, m.status, m.create_by, m.create_time, m.update_by, m.update_time, m.remark, case when r.message_id is not null then true else false end as is_read, r.read_time from sys_message m left join sys_message_read r on r.message_id = m.message_id and r.user_id = #{userId}
m.status = '1' and (m.recipient_id is null or m.recipient_id = #{message.recipientId})
AND m.message_title like concat('%', #{message.messageTitle}, '%')
AND m.message_type = #{message.messageType}
AND m.message_level = #{message.messageLevel}
AND m.biz_source = #{message.bizSource}
AND r.message_id is null
AND r.message_id is not null
AND date_format(m.create_time, '%Y-%m-%d') >= date_format(#{message.params.beginTime}, '%Y-%m-%d')
AND date_format(m.create_time, '%Y-%m-%d') <= date_format(#{message.params.endTime}, '%Y-%m-%d')
order by m.message_id desc
